 "api_contract": [
  {
   "method": "POST",
   "path": "/api/links",
   "summary": "Create a short link. Requires X-API-Key. Optional Idempotency-Key header and optional expires_at.",
   "request": "Headers:\n- X-API-Key (required)\n- Idempotency-Key (optional, 1-255 chars, not blank)\n\nJSON body LinkCreate:\n- url: string (strict http/https validation as today)\n- expires_at: ISO 8601 datetime string or null (optional)\n\nOffset values are converted to UTC, naive values are treated as UTC, and the value is stored as naive UTC. It must be strictly after the server's current time (checked in the service; the check is skipped on idempotent replay).\n\nResponse body LinkCreatedResponse: {code, short_url, url, is_active, created_at (UTC, 'Z'), expires_at (UTC 'Z' or null)}.\n\nResponse headers:\n- Location: /api/links/{code}\n- Idempotent-Replayed: true, on replay only",
   "responses": {
    "201": "Created, or idempotent replay (with Idempotent-Replayed: true); body LinkCreatedResponse including expires_at",
    "400": "Invalid Idempotency-Key header",
    "401": "Invalid or missing API key (WWW-Authenticate: ApiKey)",
    "409": "Idempotency-Key already used with a different payload (different url, or added/different/removed expires_at)",
    "422": "Invalid body or URL, expires_at not a datetime string, or expires_at at or before now ({\"detail\": \"expires_at must be in the future\"})",
    "503": "Short code allocation exhausted or database unavailable"
   },
   "fr_ids": [
    "FR-1",
    "FR-4",
    "FR-23",
    "FR-21"
   ]
  },
  {
   "method": "GET",
   "path": "/api/links/{code}",
   "summary": "Get link metadata, including deactivated and expired links. Requires X-API-Key.",
   "request": "Path code. Response body LinkDetailResponse:\n- code, short_url, url, is_active\n- created_at, deactivated_at: UTC 'Z' or null\n- expires_at: UTC 'Z' or null\n- is_expired: bool, true iff expires_at is not null and now >= expires_at\n- total_clicks: int",
   "responses": {
    "200": "LinkDetailResponse with expires_at and is_expired",
    "401": "Invalid or missing API key",
    "404": "Link not found (unknown or malformed code)"
   },
   "fr_ids": [
    "FR-6",
    "FR-23",
    "FR-22"
   ]
  },
  {
   "method": "PATCH",
   "path": "/api/links/{code}",
   "summary": "Set, change or clear the expiry of an existing link. Requires X-API-Key.",
   "request": "JSON body LinkExpiryUpdate (extra fields forbidden): {\"expires_at\": <ISO 8601 datetime string> | null}. The field is required but may be null.\n- A non-null value is normalised to naive UTC and must be strictly after now.\n- null clears the expiry.\n- The link is never reactivated.\n- url, code, is_active, created_at, deactivated_at and idempotency records are untouched.",
   "responses": {
    "200": "Updated LinkDetailResponse",
    "401": "Invalid or missing API key",
    "404": "Link not found (unknown or malformed code)",
    "422": "Missing expires_at, unknown extra fields, non-datetime value, or expires_at at or before now; stored value unchanged"
   },
   "fr_ids": [
    "FR-24"
   ]
  },
  {
   "method": "DELETE",
   "path": "/api/links/{code}",
   "summary": "Deactivate (soft-delete) a link. Idempotent. Requires X-API-Key. Unchanged.",
   "request": "Path code. No body.",
   "responses": {
    "204": "Deactivated (or already inactive)",
    "401": "Invalid or missing API key",
    "404": "Link not found"
   },
   "fr_ids": [
    "FR-7"
   ]
  },
  {
   "method": "GET",
   "path": "/api/links/{code}/stats",
   "summary": "Daily click stats. Contract unchanged; now aggregated in SQL. Requires X-API-Key.",
   "request": "Query days: int, 1..365, default 30. Response body LinkStatsResponse (unchanged): {code, total_clicks, clicks_per_day: [{date, count}], top_referrers: [{referrer, count}]}.",
   "responses": {
    "200": "LinkStatsResponse (unchanged shape and semantics; works for deactivated and expired links)",
    "401": "Invalid or missing API key",
    "404": "Link not found",
    "422": "Invalid 'days' query parameter"
   },
   "fr_ids": [
    "FR-9",
    "FR-18"
   ]
  },
  {
   "method": "GET",
   "path": "/api/links/{code}/stats/hourly",
   "summary": "Clicks per UTC hour for one link over [start, end), zero-filled. Requires X-API-Key.",
   "request": "Query parameters (optional ISO 8601 datetimes): start and end. Offsets are converted to UTC and naive values are treated as UTC. Clients must URL-encode '+' as %2B.\n\nRange rules:\n- Both omitted: start = current UTC hour - 24h, end = current UTC hour + 1h (25 buckets).\n- start is floored to the top of its hour; end is rounded up to the next top of hour (unchanged if already aligned).\n\nResponse body LinkHourlyStatsResponse: {code, start (UTC 'Z'), end (UTC 'Z'), total_clicks (sum over the range), clicks_per_hour: [{hour (UTC 'Z', top of hour), count}]}. Every hour in [start, end) is listed ascending; hours without clicks have count 0.",
   "responses": {
    "200": "LinkHourlyStatsResponse (works for active, deactivated and expired links)",
    "401": "Invalid or missing API key",
    "404": "Link not found (unknown or malformed code)",
    "422": "Only one of start/end supplied, aligned start >= aligned end, range longer than 744 hours, unparseable or out-of-range datetime"
   },
   "fr_ids": [
    "FR-25"
   ]
  },
